ART = f"{LB}/rl/artifacts/v7/13/c"
START = os.environ.get("P13_START", f"{LB}/rl/artifacts/v7/13/bc/bc.pt")
READOUTS = ["sampled", "twostage", "argmax"]
TWO = "--device cuda --logit-bound 5 --argmax-classes --argmax-two-stage"
MAINS = {  # name: (deck, starting snapshot, lane seed)
    "M_B": ("BenchDimir", START, 31),
}
ORDER = ["M_B"]
